pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // First withdrawal pays out and (in the correct contract) clears credit.
        vm.prank(actor);
        bool ok1;
        try c.withdrawAll() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first withdrawAll must succeed");

        // Rule: after a successful full withdrawal, credit is zero, so a second
        // withdrawAll is a no-op and must NOT revert for ANY admissible input.
        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "second withdrawAll must be a no-op, not revert");
    }
}

