        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.deposit{value: amount}();

        vm.prank(address(actor));
        try c.withdrawAll() {
            // succeeded
        } catch {
            // reverted
        }

        // If the withdraw did not actually transfer funds out, the credit
        // must still be intact. P reverts (failed low-level call) and keeps
        // credit == amount; the mutant requires(!callResult), proceeds on the
        // failed transfer and zeroes the credit.
        assertTrue(c.credit(address(actor)) == amount || address(c).balance == 0);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

