pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor.code.length == 0); // plain EOA: low-level call delivers ether successfully
        vm.assume(actor != address(c));
        amount = bound(amount, 1, address(this).balance / 2 + 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.deal(actor, 0);
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Rule: a legitimate withdrawAll by an EOA always succeeds and drains the contract's ether.
        // The mutant reverts the call on success, so `ok` is false and ether stays stuck in c.
        assertTrue(ok && address(c).balance == 0);
    }
}

