pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        address actor = address(reverter);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: either the withdrawal reverts (depositor keeps credit,
        // contract keeps the ether) or it succeeds fully (credit zeroed AND
        // contract balance emptied). The inverted-require mutant succeeds the
        // failed transfer path: ok==true, credit==0, but the contract's ether
        // was never sent out, so balance stays nonzero -> rule broken.
        assertTrue(!ok || (c.credit(actor) == 0 && address(c).balance == 0));
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

