pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actorA, address actorB) public {
        vm.assume(actorA != address(0) && actorB != address(0) && actorA != actorB);
        vm.assume(actorA != address(c) && actorB != address(c));
        amount = bound(amount, 1, 1e18);

        // Actor A deposits and successfully withdraws (first withdrawAll)
        vm.deal(actorA, amount);
        vm.prank(actorA);
        c.deposit{value: amount}();
        vm.prank(actorA);
        bool okA;
        try c.withdrawAll() { okA = true; } catch { okA = false; }
        assertTrue(okA, "first withdrawAll should succeed for funded account");

        // Actor B, with its own credit, must also be able to withdraw afterwards
        vm.deal(actorB, amount);
        vm.prank(actorB);
        c.deposit{value: amount}();
        vm.prank(actorB);
        bool okB;
        try c.withdrawAll() { okB = true; } catch { okB = false; }

        // General rule: withdrawal of any account's own credit always succeeds;
        // the mutant leaves the lock set forever, so B's withdrawal reverts.
        assertTrue(okB, "second account's withdrawAll must succeed");
    }
}

