import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address a1, address a2) public {
        vm.assume(amount > 0 && amount < 1e30);
        vm.assume(a1 != a2);
        vm.assume(a1 != address(c) && a2 != address(c));
        vm.assume(a1 != address(this) && a2 != address(this));

        // both accounts deposit
