        vm.prank(a1);
        c.deposit{value: amount}();
        vm.deal(a2, amount);
        vm.prank(a2);
        c.deposit{value: amount}();

        // first account withdraws all (no value attached: withdrawAll is non-payable)
        vm.prank(a1);
        c.withdrawAll();

        // RULE: after any successful withdrawAll, a second distinct funded account
        // can still withdrawAll successfully.
        vm.prank(a2);
        try c.withdrawAll() {
            assertTrue(address(c).balance == 0, "second withdrawal must drain contract");
        } catch {
            assertTrue(false, "second account's withdrawAll must succeed");
        }
    }
}

