pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 extra) public {
        amount = bound(amount, 1, 10 ether);
        extra = bound(extra, amount, 100 ether);

        attacker = new Attacker(c, amount);
        address funder = makeAddr("funder");

        // fund the contract with slack so the mutant's re-entry can succeed arithmetically
        vm.deal(funder, extra);
        vm.prank(funder);
        c.deposit{value: extra}();

        vm.deal(address(attacker), amount);

        uint256 attackerStart = address(attacker).balance;
        bool ok;
        try attacker.go() { ok = true; } catch { ok = false; }

        // General rule: no party can extract more ether from C than its own credit,
        // even when its receive() re-enters withdrawAll.
        uint256 gained = address(attacker).balance - attackerStart;
        assertTrue(gained <= amount && (!ok || address(c).balance() >= 0));
    }
}

contract Attacker {
    C c;
    uint256 amt;
    bool reentered;

    constructor(C _c, uint256 _amt) { c = _c; amt = _amt; }

    function go() external {
        c.deposit{value: amt}();
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered && address(c).balance >= amt) {
            reentered = true;
            c.withdrawAll();
        }
    }
}
